CREATE TABLE projects(id TEXT PRIMARY KEY, common_dir TEXT NOT NULL UNIQUE, prefix TEXT NOT NULL, next_ticket INTEGER NOT NULL DEFAULT 1, next_problem INTEGER NOT NULL DEFAULT 1);
CREATE TABLE worktrees(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), root TEXT NOT NULL, branch TEXT, head TEXT NOT NULL DEFAULT '', UNIQUE(project_id,root));
CREATE TABLE agents(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), name TEXT NOT NULL CHECK(name <> 'none'), role TEXT NOT NULL DEFAULT '', provider TEXT NOT NULL DEFAULT '', UNIQUE(project_id,name), UNIQUE(project_id,id));
CREATE TABLE sessions(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), agent_id TEXT NOT NULL, declared_state TEXT NOT NULL DEFAULT 'active' CHECK(declared_state IN('active','idle','stopped')), last_seen_at TEXT NOT NULL, worktree_root TEXT NOT NULL, branch TEXT, head TEXT NOT NULL DEFAULT '', UNIQUE(project_id,id), FOREIGN KEY(project_id,agent_id) REFERENCES agents(project_id,id));
CREATE TABLE tickets(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), display_key TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'ready' CHECK(state IN('ready','in_progress','review','done')), revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0), assigned_agent_id TEXT, summary TEXT NOT NULL DEFAULT '', evidence TEXT NOT NULL DEFAULT '', qa TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(project_id,id), UNIQUE(project_id,display_key), FOREIGN KEY(project_id,assigned_agent_id) REFERENCES agents(project_id,id));
CREATE TABLE claims(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), ticket_id TEXT NOT NULL, session_id TEXT NOT NULL, created_at TEXT NOT NULL, released_at TEXT, worktree_root TEXT NOT NULL DEFAULT '', branch TEXT, head TEXT NOT NULL DEFAULT '', UNIQUE(project_id,id), FOREIGN KEY(project_id,ticket_id) REFERENCES tickets(project_id,id), FOREIGN KEY(project_id,session_id) REFERENCES sessions(project_id,id));
CREATE UNIQUE INDEX active_ticket_claim ON claims(ticket_id) WHERE released_at IS NULL;
CREATE UNIQUE INDEX active_session_claim ON claims(session_id) WHERE released_at IS NULL;
CREATE TABLE problems(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), display_key TEXT NOT NULL, ticket_id TEXT, session_id TEXT NOT NULL, summary TEXT NOT NULL CHECK(length(summary)<=4096), expected TEXT NOT NULL CHECK(length(expected)<=65536), actual TEXT NOT NULL CHECK(length(actual)<=65536), correction TEXT NOT NULL DEFAULT '' CHECK(length(correction)<=65536), evidence TEXT NOT NULL DEFAULT '' CHECK(length(evidence)<=65536), created_at TEXT NOT NULL, UNIQUE(project_id,id), UNIQUE(project_id,display_key), FOREIGN KEY(project_id,ticket_id) REFERENCES tickets(project_id,id), FOREIGN KEY(project_id,session_id) REFERENCES sessions(project_id,id));
CREATE TABLE events(seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, project_id TEXT NOT NULL REFERENCES projects(id), ticket_id TEXT, problem_id TEXT, actor_id TEXT NOT NULL, kind TEXT NOT NULL, body TEXT NOT NULL DEFAULT '', payload TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, FOREIGN KEY(project_id,ticket_id) REFERENCES tickets(project_id,id), FOREIGN KEY(project_id,problem_id) REFERENCES problems(project_id,id));
CREATE TABLE requests(project_id TEXT NOT NULL, request_id TEXT NOT NULL, operation TEXT NOT NULL, actor_id TEXT NOT NULL, payload_hash TEXT NOT NULL, result TEXT NOT NULL, PRIMARY KEY(project_id,request_id));
